var chapPed12 = {
    name: "🦠 الفصل الثاني عشر: Nursing Care of Children Suffering from Communicable Disease",
    icon: "fas fa-virus",
    definitions: [
        { text: "Communicable disease: Illnesses caused by viruses or bacteria that spread from one person to another through contact with contaminated surfaces, bodily fluids, blood products, insect bites, or through the air.", translation: "المرض المعدي: مرض تسببه الفيروسات أو البكتيريا وينتقل من شخص لآخر عبر ملامسة أسطح ملوثة أو سوائل الجسم أو منتجات الدم أو لدغات الحشرات أو عبر الهواء." },
        { text: "Immunization: The inclusive term denoting the process of inducing or providing active or passive immunity artificially by administering an immunobiologic.", translation: "التمنيع: مصطلح شامل يشير إلى عملية إحداث أو توفير مناعة فعالة أو سلبية بشكل اصطناعي عن طريق إعطاء مستحضر مناعي حيوي." },
        { text: "Immunity: An inherited or acquired state in which an individual is resistant to the occurrence or the effects of a specific disease, particularly an infectious agent.", translation: "المناعة: حالة موروثة أو مكتسبة يكون فيها الفرد مقاوماً لحدوث مرض معين أو لتأثيراته، وخاصة العامل المُعدي." },
        { text: "Natural immunity: Innate immunity or resistance to infection or toxicity, present without prior exposure to the specific agent.", translation: "المناعة الطبيعية: مناعة فطرية أو مقاومة للعدوى أو السمية، موجودة دون تعرض سابق للعامل المحدد." },
        { text: "Acquired immunity: Immunity resulting from exposure to the invading agent, either bacteria, virus, or toxin.", translation: "المناعة المكتسبة: مناعة ناتجة عن التعرض للعامل الغازي، سواء كان بكتيريا أو فيروساً أو سُماً." },
        { text: "Active immunity: A state where immune bodies are actively formed against specific antigens, either naturally by having had the disease clinically or subclinically, or artificially by introducing the antigen into the individual.", translation: "المناعة الفعالة: حالة تتكون فيها أجسام مناعية بفعالية ضد مستضدات معينة، إما طبيعياً بالإصابة بالمرض سريرياً أو دون أعراض، أو اصطناعياً بإدخال المستضد إلى الجسم." },
        { text: "Passive immunity: Temporary immunity obtained by transfusing immunoglobulins or antitoxins, either artificially from another human or animal actively immunized against an antigen, or naturally from the mother to the fetus via the placenta.", translation: "المناعة السلبية: مناعة مؤقتة تُكتسب بنقل الغلوبولينات المناعية أو مضادات السموم، إما اصطناعياً من إنسان أو حيوان مُمَنَّع فعلياً ضد مستضد، أو طبيعياً من الأم إلى الجنين عبر المشيمة." },
        { text: "Vaccine: A suspension of live (usually attenuated) or inactivated microorganisms, or fractions of a microorganism, that induces immunity and prevents infectious disease.", translation: "اللقاح: معلق من كائنات دقيقة حية (عادة مُضعَّفة) أو معطَّلة، أو أجزاء من كائن دقيق، يُحدث مناعة ويقي من الأمراض المعدية." },
        { text: "Poliomyelitis: A communicable disease caused by enteroviruses, transmitted by the fecal-oral and pharyngeal-oropharyngeal routes, that may present in abortive, nonparalytic, or paralytic forms affecting the central nervous system.", translation: "شلل الأطفال: مرض مُعدٍ تسببه الفيروسات المعوية، ينتقل عبر الطريقين البرازي الفموي والبلعومي الفموي، وقد يظهر بشكل خفي أو غير شللي أو شللي يصيب الجهاز العصبي المركزي." },
        { text: "Measles (Rubeola): A viral communicable disease transmitted mainly by direct contact with respiratory droplets, characterized by a prodromal catarrhal stage with Koplik spots followed by an erythematous maculopapular rash.", translation: "الحصبة: مرض فيروسي مُعدٍ ينتقل أساساً بالتلامس المباشر مع رذاذ الجهاز التنفسي، ويتميز بمرحلة نزلية بادرية تظهر فيها بقع كوبليك تليها طفح جلدي حطاطي احمراري." },
        { text: "Chickenpox (Varicella): A communicable disease caused by the varicella-zoster virus, spread by direct contact, droplet, and contaminated objects, producing a highly pruritic rash that progresses through macule, papule, vesicle, and crust stages.", translation: "جدري الماء: مرض مُعدٍ يسببه فيروس النطاق الحماقي (VZV)، ينتقل بالتلامس المباشر والرذاذ والأدوات الملوثة، ويُحدث طفحاً شديد الحكة يمر بمراحل البقعة والحطاطة والحويصلة والقشرة." },
        { text: "Diphtheria: A communicable disease caused by Corynebacterium diphtheriae, transmitted by direct contact with an infected person, a carrier, or contaminated articles, characterized by a smooth, adherent white or gray membrane in the tonsillar-pharyngeal area.", translation: "الخُناق: مرض مُعدٍ تسببه جرثومة Corynebacterium diphtheriae، ينتقل بالتلامس المباشر مع شخص مصاب أو حامل للجرثومة أو أدوات ملوثة، ويتميز بغشاء أبيض أو رمادي أملس لاصق في منطقة اللوزتين والبلعوم." },
        { text: "Mumps: A communicable disease caused by paramyxovirus, transmitted by direct contact with or droplet spread from an infected person, characterized by parotid gland swelling accompanied by pain and tenderness.", translation: "النكاف: مرض مُعدٍ يسببه فيروس الباراميكسو، ينتقل بالتلامس المباشر أو الرذاذ من شخص مصاب، ويتميز بتورم الغدة النكفية مصحوباً بألم وإيلام." },
        { text: "Tetanus: A disease caused by Clostridium tetani spores that enter the body through wounds such as puncture wounds, burns, or crushed areas, producing muscle rigidity and spasms.", translation: "الكزاز: مرض تسببه أبواغ جرثومة Clostridium tetani التي تدخل الجسم عبر جروح كالجروح الثاقبة أو الحروق أو المناطق المسحوقة، وتُحدث تصلباً وتشنجات عضلية." },
        { text: "Tuberculosis: A communicable disease caused by Mycobacterium tuberculosis, transmitted through tiny droplets released into the air via coughs and sneezes, most commonly affecting the lungs.", translation: "السل: مرض مُعدٍ تسببه جرثومة Mycobacterium tuberculosis، ينتقل عبر رذاذ دقيق يُطلق في الهواء بالسعال والعطس، ويصيب الرئتين غالباً." },
        { text: "Typhoid fever: An infection caused by Salmonella typhi, transmitted through the fecal-oral route via contaminated food or water, presenting with abdominal pain, diarrhea, nausea, vomiting, and high fever.", translation: "حمى التيفويد: عدوى تسببها جرثومة Salmonella typhi، تنتقل عبر الطريق البرازي الفموي من خلال الطعام أو الماء الملوث، وتظهر بألم بطني وإسهال وغثيان وقيء وحمى مرتفعة." }
    ],
    complete: [
        { text: "The causative agent of poliomyelitis is _________.", translation: "العامل المسبب لشلل الأطفال هو _________.", completion: "Enteroviruses", completionTranslation: "الفيروسات المعوية" },
        { text: "Poliomyelitis is transmitted via the _________ and pharyngeal-oropharyngeal routes.", translation: "ينتقل شلل الأطفال عبر الطريق _________ والبلعومي الفموي.", completion: "fecal-oral", completionTranslation: "البرازي الفموي" },
        { text: "The incubation period of poliomyelitis is usually _________ days.", translation: "فترة حضانة شلل الأطفال عادةً _________ يوماً.", completion: "7 to 14", completionTranslation: "7 إلى 14" },
        { text: "In paralytic poliomyelitis, the initial course is followed by recovery and then signs of _________ paralysis.", translation: "في شلل الأطفال الشللي، يتبع المسار الأولي تعافٍ ثم تظهر علامات شلل _________.", completion: "central nervous system", completionTranslation: "الجهاز العصبي المركزي" },
        { text: "The causative agent of measles is a _________.", translation: "العامل المسبب للحصبة هو _________.", completion: "virus", completionTranslation: "فيروس" },
        { text: "The incubation period of measles is _________ days.", translation: "فترة حضانة الحصبة _________ يوماً.", completion: "10 to 20", completionTranslation: "10 إلى 20" },
        { text: "_________ spots are a characteristic sign of measles that appear during the prodromal (catarrhal) stage.", translation: "بقع _________ علامة مميزة للحصبة تظهر خلال المرحلة النزلية البادرية.", completion: "Koplik", completionTranslation: "كوبليك" },
        { text: "Measles rash begins as an erythematous maculopapular eruption on the _________ and spreads downward.", translation: "يبدأ طفح الحصبة كثوران حطاطي احمراري على _________ وينتشر نزولاً.", completion: "face", completionTranslation: "الوجه" },
        { text: "Treatment for measles includes supplementation with vitamin _________.", translation: "يشمل علاج الحصبة إعطاء مكمل فيتامين _________.", completion: "A", completionTranslation: "أ" },
        { text: "Chickenpox is caused by the _________ virus.", translation: "يسبب جدري الماء فيروس _________.", completion: "varicella-zoster (VZV)", completionTranslation: "النطاق الحماقي (VZV)" },
        { text: "The incubation period of chickenpox is usually _________ days.", translation: "فترة حضانة جدري الماء عادةً _________ يوماً.", completion: "14 to 16", completionTranslation: "14 إلى 16" },
        { text: "The antiviral agent used in treatment of chickenpox is _________.", translation: "العامل المضاد للفيروسات المستخدم في علاج جدري الماء هو _________.", completion: "acyclovir (Zovirax)", completionTranslation: "الأسيكلوفير (Zovirax)" },
        { text: "_________ should be avoided in children with chickenpox due to the risk of Reye syndrome.", translation: "يجب تجنب _________ لدى الأطفال المصابين بجدري الماء لخطر الإصابة بمتلازمة راي.", completion: "Aspirin", completionTranslation: "الأسبرين" },
        { text: "The causative agent of diphtheria is _________.", translation: "العامل المسبب للخُناق هو _________.", completion: "Corynebacterium diphtheriae", completionTranslation: "Corynebacterium diphtheriae" },
        { text: "In tonsillar-pharyngeal diphtheria, a smooth, adherent, white or gray _________ forms.", translation: "في خُناق اللوزتين والبلعوم، يتشكل _________ أملس لاصق أبيض أو رمادي.", completion: "membrane", completionTranslation: "غشاء" },
        { text: "Pronounced lymphadenitis in severe diphtheria is referred to as \"_________.\"", translation: "يُشار إلى التهاب الغدد اللمفاوية الواضح في الخُناق الشديد بمصطلح \"_________.\"", completion: "bull's neck", completionTranslation: "عنق الثور (bull's neck)" },
        { text: "The causative agent of mumps is _________.", translation: "العامل المسبب للنكاف هو _________.", completion: "paramyxovirus", completionTranslation: "فيروس الباراميكسو" },
        { text: "The incubation period of mumps is _________ days.", translation: "فترة حضانة النكاف _________ يوماً.", completion: "14 to 21", completionTranslation: "14 إلى 21" },
        { text: "A serious complication of mumps affecting hearing is _________ deafness.", translation: "من المضاعفات الخطيرة للنكاف التي تؤثر على السمع الصمم _________.", completion: "sensorineural", completionTranslation: "الحسي العصبي" },
        { text: "The causative agent of tetanus is _________.", translation: "العامل المسبب للكزاز هو _________.", completion: "Clostridium tetani", completionTranslation: "Clostridium tetani" },
        { text: "The incubation period of tetanus averages _________ days.", translation: "تبلغ فترة حضانة الكزاز في المتوسط _________ أيام.", completion: "8", completionTranslation: "8" },
        { text: "_________ is administered for seizure control in tetanus.", translation: "يُعطى دواء _________ للسيطرة على النوبات في الكزاز.", completion: "Diazepam", completionTranslation: "الديازيبام" },
        { text: "The causative agent of tuberculosis is _________.", translation: "العامل المسبب للسل هو _________.", completion: "Mycobacterium tuberculosis", completionTranslation: "Mycobacterium tuberculosis" },
        { text: "The standard antimicrobial drug given as a daily dose for 9 months in tuberculosis treatment is _________.", translation: "الدواء المضاد للميكروبات الأساسي الذي يُعطى بجرعة يومية لمدة 9 أشهر في علاج السل هو _________.", completion: "isoniazid (INH)", completionTranslation: "الأيزونيازيد (INH)" },
        { text: "Typhoid fever is caused by _________.", translation: "تسبب حمى التيفويد جرثومة _________.", completion: "Salmonella typhi", completionTranslation: "Salmonella typhi" },
        { text: "Typhoid fever is transmitted via the _________ route.", translation: "تنتقل حمى التيفويد عبر الطريق _________.", completion: "fecal-oral", completionTranslation: "البرازي الفموي" },
        { text: "According to the Egyptian obligatory immunization schedule, the BCG vaccine is given at _________.", translation: "حسب جدول التطعيمات الإجبارية المصري، يُعطى لقاح BCG عند _________.", completion: "birth", completionTranslation: "الولادة" },
        { text: "The Measles, Mumps, and Rubella (MMR) vaccine is first given at _________ months of age in Egypt.", translation: "يُعطى لقاح الحصبة والنكاف والحصبة الألمانية (MMR) للمرة الأولى عند عمر _________ شهراً في مصر.", completion: "12", completionTranslation: "12" }
    ],
    list: [
        { text: "Examples of communicable diseases discussed in this chapter", translation: "أمثلة على الأمراض المعدية التي تناولها هذا الفصل", items: ["1- Poliomyelitis - شلل الأطفال", "2- Measles - الحصبة", "3- Chickenpox - جدري الماء", "4- Diphtheria - الخُناق", "5- Mumps - النكاف", "6- Tetanus - الكزاز", "7- Tuberculosis - السل"] },
        { text: "The three clinical forms of poliomyelitis", translation: "الأشكال السريرية الثلاثة لشلل الأطفال", items: ["1- Abortive or inapparent: fever, uneasiness, sore throat, headache, anorexia, vomiting, abdominal pain lasting a few hours to a few days - خفي أو غير ظاهر: حمى وعدم راحة والتهاب حلق وصداع وفقدان شهية وقيء وألم بطني يستمر ساعات إلى أيام", "2- Nonparalytic: same manifestations as abortive but more severe, with pain and stiffness in neck, back, and legs - غير شللي: نفس أعراض الشكل الخفي لكن أشد، مع ألم وتيبس في الرقبة والظهر والساقين", "3- Paralytic: initial course similar to nonparalytic, followed by recovery then signs of central nervous system paralysis - شللي: مسار أولي شبيه بالشكل غير الشللي، يتبعه تعافٍ ثم ظهور علامات شلل بالجهاز العصبي المركزي"] },
        { text: "Complications of poliomyelitis", translation: "مضاعفات شلل الأطفال", items: ["1- Permanent paralysis - شلل دائم", "2- Respiratory arrest - توقف تنفسي", "3- Hypertension - ارتفاع ضغط الدم", "4- Kidney stones from demineralization of bone during prolonged immobility - حصوات كلوية بسبب نزع المعادن من العظام أثناء الخمول الطويل"] },
        { text: "Nursing care management of poliomyelitis", translation: "الرعاية التمريضية لشلل الأطفال", items: ["1- Contact Precautions - احتياطات التلامس", "2- Administer mild sedatives as necessary to relieve anxiety and promote rest - إعطاء مهدئات خفيفة عند الحاجة لتخفيف القلق وتعزيز الراحة", "3- Participate in physical therapy (moist hot packs, range-of-motion exercises) - المشاركة في العلاج الطبيعي (كمادات حارة رطبة وتمارين مدى الحركة)", "4- Position child to maintain body alignment and prevent contractures or skin breakdown - وضع الطفل بما يحافظ على استقامة الجسم ويمنع التقلصات أو تلف الجلد", "5- Use footboard to prevent footdrop; use pressure mattress for prolonged immobility - استخدام لوح قدم لمنع سقوط القدم؛ واستخدام فرشة ضغط عند الخمول الطويل", "6- Encourage activities of daily living to capability; promote early ambulation with assistive devices - تشجيع أنشطة الحياة اليومية حسب القدرة؛ وتعزيز المشي المبكر بالأجهزة المساعدة", "7- Administer analgesics for comfort during activity; give high-protein diet and bowel management - إعطاء مسكنات للراحة أثناء النشاط؛ وتقديم نظام غذائي غني بالبروتين وإدارة الإخراج", "8- Observe for respiratory paralysis (difficulty talking, ineffective cough, shallow rapid respirations) and report to practitioner - مراقبة علامات الشلل التنفسي (صعوبة الكلام، سعال غير فعال، تنفس سطحي سريع) وإبلاغ الطبيب"] },
        { text: "Clinical manifestation stages of measles", translation: "مراحل المظاهر السريرية للحصبة", items: ["1- Prodromal (catarrhal) stage: fever and malaise, followed by coryza, cough, conjunctivitis, and Koplik spots - المرحلة النزلية البادرية: حمى وتوعك، تليها زكام وسعال والتهاب ملتحمة وبقع كوبليك", "2- Rash: appears 3-4 days after onset of prodromal stage, begins as erythematous maculopapular eruption on face and spreads downward - الطفح: يظهر بعد 3-4 أيام من بدء المرحلة البادرية، يبدأ كثوران حطاطي احمراري على الوجه وينتشر نزولاً", "3- Constitutional signs and symptoms: anorexia, abdominal pain, malaise, generalized lymphadenopathy - أعراض عامة: فقدان شهية وألم بطني وتوعك وتضخم عام في الغدد اللمفاوية"] },
        { text: "Complications of measles", translation: "مضاعفات الحصبة", items: ["1- Otitis media - التهاب الأذن الوسطى", "2- Pneumonia (bacterial) - الالتهاب الرئوي (البكتيري)", "3- Obstructive laryngitis and laryngotracheitis - التهاب حنجرة انسدادي والتهاب الحنجرة والقصبة", "4- Encephalitis (rare but has high mortality) - التهاب الدماغ (نادر لكن معدل وفياته مرتفع)"] },
        { text: "Nursing care management of measles", translation: "الرعاية التمريضية للحصبة", items: ["1- Maintain isolation until fifth day of rash; encourage rest during prodromal stage - عزل حتى اليوم الخامس من ظهور الطفح؛ وتشجيع الراحة خلال المرحلة البادرية", "2- For fever: instruct parents to give antipyretics, avoid chilling, institute seizure precautions if prone to seizures - للحمى: تعليم الأهل بإعطاء خافضات الحرارة، وتجنب البرد، واتخاذ احتياطات النوبات إن كان الطفل عرضة لها", "3- For coryza/cough: use cool-mist vaporizer, protect skin around nares with petrolatum, encourage fluids and soft bland foods - للزكام والسعال: استخدام مرطب بخار بارد، وحماية الجلد حول الأنف بالفازلين، وتشجيع السوائل والأطعمة الطرية", "4- For skin care: keep skin clean, use tepid baths as necessary - للعناية بالجلد: الحفاظ على نظافته، واستخدام حمامات فاترة عند الحاجة", "5- For eye care: dim lights if photophobia present, clean eyelids with warm saline to remove secretions, keep child from rubbing eyes - للعناية بالعين: تخفيف الإضاءة عند وجود رهاب الضوء، وتنظيف الجفون بمحلول ملحي دافئ لإزالة الإفرازات، ومنع الطفل من فرك عينيه"] },
        { text: "Progression and characteristics of the chickenpox rash", translation: "تطور وخصائص طفح جدري الماء", items: ["1- Begins as macule, rapidly progresses to papule and then vesicle - يبدأ كبقعة، ويتطور سريعاً إلى حطاطة ثم حويصلة", "2- Becomes umbilicated and cloudy, breaks easily, and forms crusts - يصبح مسرّراً وعكراً، ويتقشر بسهولة ويكوّن قشوراً", "3- All three stages (papule, vesicle, crust) may be present at varying degrees at one time - قد توجد المراحل الثلاث (حطاطة، حويصلة، قشرة) بدرجات متفاوتة في وقت واحد", "4- Distribution is centripetal, spreading to face and proximal extremities but sparse on distal limbs - التوزيع مركزي، ينتشر إلى الوجه والأطراف القريبة لكنه متناثر في الأطراف البعيدة", "5- Rash is highly pruritic - الطفح شديد الحكة"] },
        { text: "Complications of chickenpox", translation: "مضاعفات جدري الماء", items: ["1- Secondary bacterial infections - عدوى بكتيرية ثانوية", "2- Encephalitis - التهاب الدماغ", "3- Varicella pneumonia (rare in normal children) - التهاب رئوي بجدري الماء (نادر لدى الأطفال الأصحاء)", "4- Hemorrhagic varicella - جدري ماء نزفي", "5- Chronic or transient thrombocytopenia - نقص صفيحات دموية مزمن أو عابر"] },
        { text: "Nursing care management of chickenpox", translation: "الرعاية التمريضية لجدري الماء", items: ["1- Maintain Standard, Airborne, and Contact Precautions - الحفاظ على الاحتياطات القياسية والمحمولة جواً والتلامسية", "2- Keep child at home away from susceptible individuals until vesicles have dried (usually 1 week) - إبقاء الطفل بالمنزل بعيداً عن الأشخاص المعرضين حتى جفاف الحويصلات (عادة أسبوع واحد)", "3- Skin care: daily bath and change of clothes/linens, apply topical calamine lotion, keep nails short and clean, apply mittens if child scratches - العناية بالجلد: استحمام يومي وتغيير الملابس والأغطية، ووضع كالامين موضعي، وتقليم الأظافر، واستخدام قفازات عند الحك", "4- Keep child cool (may decrease number of lesions) and occupied to lessen pruritus - إبقاء الطفل بارداً (قد يقلل عدد الآفات) ومشغولاً لتخفيف الحكة", "5- Remove loose crusts that irritate skin; teach child to apply pressure to pruritic area instead of scratching - إزالة القشور المرتخية المهيّجة؛ وتعليم الطفل الضغط على المنطقة المثيرة للحكة بدلاً من حكّها", "6- Avoid use of aspirin - تجنب استخدام الأسبرين"] },
        { text: "Clinical forms of diphtheria", translation: "الأشكال السريرية للخُناق", items: ["1- Nasal: resembles common cold with mucopurulent nasal discharge and possible frank epistaxis - الأنفي: يشبه الزكام مع إفرازات أنفية مخاطية قيحية واحتمال نزيف أنفي واضح", "2- Tonsillar-pharyngeal: malaise, anorexia, sore throat, low-grade fever, a smooth adherent white or gray membrane, pronounced lymphadenitis (\"bull's neck\"), and in severe cases toxemia and septic shock - اللوزي البلعومي: توعك وفقدان شهية والتهاب حلق وحمى خفيفة وغشاء أبيض أو رمادي لاصق وتضخم لمفاوي واضح (\"عنق الثور\")، وفي الحالات الشديدة تسمم دموي وصدمة إنتانية", "3- Laryngeal: fever, hoarseness, cough, potential airway obstruction, apprehension, dyspneic retractions, and cyanosis - الحنجري: حمى وبحة صوت وسعال واحتمال انسداد مجرى الهواء وقلق وتراجعات تنفسية وزُراق"] },
        { text: "Nursing care management of diphtheria", translation: "الرعاية التمريضية للخُناق", items: ["1- Follow Standard and Droplet Precautions until two cultures are negative for C. diphtheriae - اتباع الاحتياطات القياسية والمحمولة بالرذاذ حتى تصبح زراعتان سلبيتين لجرثومة الخُناق", "2- Use Contact Precautions with cutaneous manifestations - استخدام احتياطات التلامس عند وجود مظاهر جلدية", "3- Administer antibiotics in a timely manner; participate in sensitivity testing; keep epinephrine available - إعطاء المضادات الحيوية في وقتها؛ والمشاركة في اختبار الحساسية؛ وتوفير الإبينفرين", "4- Administer complete care to maintain bed rest; use suctioning as needed - تقديم رعاية شاملة للحفاظ على الراحة بالفراش؛ واستخدام الشفط عند الحاجة", "5- Observe respiration for signs of obstruction; administer humidified oxygen as prescribed - مراقبة التنفس لعلامات الانسداد؛ وإعطاء أكسجين مرطب حسب الوصفة"] },
        { text: "Complications of mumps", translation: "مضاعفات النكاف", items: ["1- Sensorineural deafness - صمم حسي عصبي", "2- Postinfectious encephalitis - التهاب دماغ تالٍ للعدوى", "3- Myocarditis, arthritis, hepatitis - التهاب عضلة القلب، والتهاب المفاصل، والتهاب الكبد", "4- Epididymoorchitis and oophoritis - التهاب البربخ والخصية، والتهاب المبيض", "5- Pancreatitis; sterility (extremely rare in adult men); meningitis - التهاب البنكرياس؛ العقم (نادر جداً لدى الرجال البالغين)؛ التهاب السحايا"] },
        { text: "Nursing care management of mumps", translation: "الرعاية التمريضية للنكاف", items: ["1- Maintain isolation during period of communicability - العزل خلال فترة العدوى", "2- Institute Droplet and Contact Precautions during hospitalization - اتخاذ احتياطات الرذاذ والتلامس أثناء التنويم", "3- Encourage rest and decreased activity; give analgesics for pain - تشجيع الراحة وتقليل النشاط؛ وإعطاء مسكنات للألم", "4- Encourage fluids and soft bland foods; avoid foods requiring chewing - تشجيع السوائل والأطعمة الطرية؛ وتجنب الأطعمة التي تحتاج مضغاً", "5- Apply hot or cold compresses to the neck, whichever is more comforting - وضع كمادات ساخنة أو باردة على الرقبة، أيهما أكثر راحة للطفل"] },
        { text: "Clinical manifestations of generalized tetanus", translation: "المظاهر السريرية للكزاز المعمم", items: ["1- Jaw cramping and sudden involuntary muscle spasms, often in the stomach - تشنج الفك وتشنجات عضلية لا إرادية مفاجئة، غالباً في البطن", "2- Painful muscle stiffness all over the body; trouble swallowing - تيبس عضلي مؤلم في كل الجسم؛ صعوبة في البلع", "3- Seizures (jerking or staring); headache; fever and sweating - نوبات (تشنج أو تحديق)؛ صداع؛ حمى وتعرق", "4- Changes in blood pressure and heart rate; highly sensitive to external stimuli such as noise, touch, or bright light - تغيرات في ضغط الدم ومعدل ضربات القلب؛ حساسية شديدة للمؤثرات الخارجية كالضوضاء واللمس والضوء الساطع", "5- Rapid pulse, sweating, anxious expression; possible respiratory arrest, atelectasis, and pneumonia - نبض سريع وتعرق وتعبير قلق؛ واحتمال توقف تنفسي وانخماص رئوي والتهاب رئوي"] },
        { text: "Therapeutic management of tetanus", translation: "الإدارة العلاجية للكزاز", items: ["1- Tetanus immunization - تطعيم ضد الكزاز", "2- Antibiotics - مضادات حيوية", "3- Maintaining adequate airway and fluid/electrolyte balance - الحفاظ على مجرى هواء ملائم وتوازن السوائل والإلكتروليتات", "4- Providing pain management and ensuring adequate caloric intake - توفير إدارة للألم وضمان مدخول كافٍ من السعرات الحرارية", "5- Tetanus immune globulin (TIG) therapy and local wound care - العلاج بالغلوبولين المناعي للكزاز (TIG) والعناية الموضعية بالجرح", "6- Diazepam for seizure control - الديازيبام للسيطرة على النوبات"] },
        { text: "Nursing care management of tuberculosis", translation: "الرعاية التمريضية للسل", items: ["1- Restrict child from vigorous activities such as competitive games and contact sports; protect from stress - تقييد الأنشطة الشاقة كالألعاب التنافسية والرياضات التلامسية؛ وحماية الطفل من الضغوط النفسية", "2- Continue regular immunization schedule and maintain optimum health with proper diet, adequate rest, and avoidance of infection - الاستمرار بجدول التطعيمات المعتاد والحفاظ على صحة مثلى بغذاء مناسب وراحة كافية وتجنب العدوى", "3- Obtain sputum specimens early in the morning before breakfast - أخذ عينات البلغم باكراً صباحاً قبل الإفطار", "4- Instruct patient to use tissue when coughing/sneezing; educate about tissue disposal and handwashing - تعليم المريض استخدام المناديل عند السعال والعطس؛ والتثقيف حول التخلص منها وغسل اليدين", "5- Monitor temperature; explain importance of uninterrupted drug therapy - مراقبة درجة الحرارة؛ وشرح أهمية الاستمرار دون انقطاع في العلاج الدوائي"] },
        { text: "Egyptian obligatory immunization schedule for children (age → vaccine)", translation: "جدول التطعيمات الإجبارية للأطفال في مصر (العمر ← اللقاح)", items: ["1- At birth: Oral Polio Vaccine (OPV) and BCG - عند الولادة: لقاح شلل الأطفال الفموي و BCG", "2- 2 months: OPV and Penta vaccine (Diphtheria, Tetanus, Pertussis, Hepatitis B, Haemophilus influenzae) - شهرين: لقاح شلل الأطفال الفموي واللقاح الخماسي", "3- 4 months: OPV and Penta vaccine - 4 أشهر: لقاح شلل الأطفال الفموي واللقاح الخماسي", "4- 6 months: OPV and Penta vaccine - 6 أشهر: لقاح شلل الأطفال الفموي واللقاح الخماسي", "5- 9 months: OPV, and first dose of vitamin A - 9 أشهر: لقاح شلل الأطفال الفموي، والجرعة الأولى من فيتامين أ", "6- 12 months: OPV and MMR (Measles, Mumps, Rubella) - 12 شهراً: لقاح شلل الأطفال الفموي ولقاح MMR", "7- 18 months (booster dose): OPV, DPT (Diphtheria, Tetanus, Pertussis), MMR, and second dose of vitamin A - 18 شهراً (جرعة منشطة): لقاح شلل الأطفال الفموي، ولقاح DPT، ولقاح MMR، والجرعة الثانية من فيتامين أ"] }
    ],
    mcq: [
        { text: "Communicable diseases are illnesses caused by:", translation: "الأمراض المعدية هي أمراض تسببها:", options: ["A) Viruses or bacteria", "B) Genetic mutations only", "C) Nutritional deficiencies", "D) Physical trauma"], correct: "A", correctTranslation: "أ: الفيروسات أو البكتيريا" },
        { text: "The causative agent of poliomyelitis is:", translation: "العامل المسبب لشلل الأطفال هو:", options: ["A) Enteroviruses", "B) Corynebacterium diphtheriae", "C) Clostridium tetani", "D) Salmonella typhi"], correct: "A", correctTranslation: "أ: الفيروسات المعوية" },
        { text: "Which form of poliomyelitis is characterized by central nervous system paralysis following an initial course similar to the nonparalytic type?", translation: "أي شكل من أشكال شلل الأطفال يتميز بشلل الجهاز العصبي المركزي بعد مسار أولي مشابه للشكل غير الشللي؟", options: ["A) Abortive", "B) Nonparalytic", "C) Paralytic", "D) Subclinical"], correct: "C", correctTranslation: "ج: الشللي (Paralytic)" },
        { text: "Which vitamin is given as a supplemental treatment in measles?", translation: "أي فيتامين يُعطى كعلاج مكمل في الحصبة؟", options: ["A) Vitamin A", "B) Vitamin B12", "C) Vitamin C", "D) Vitamin D"], correct: "A", correctTranslation: "أ: فيتامين أ" },
        { text: "Koplik spots are a diagnostic sign of:", translation: "بقع كوبليك علامة تشخيصية لمرض:", options: ["A) Measles", "B) Chickenpox", "C) Mumps", "D) Diphtheria"], correct: "A", correctTranslation: "أ: الحصبة" },
        { text: "The causative agent of chickenpox is:", translation: "العامل المسبب لجدري الماء هو:", options: ["A) Varicella-zoster virus", "B) Paramyxovirus", "C) Enterovirus", "D) Mycobacterium tuberculosis"], correct: "A", correctTranslation: "أ: فيروس النطاق الحماقي (VZV)" },
        { text: "Which medication should be avoided in a child with chickenpox due to the risk of Reye syndrome?", translation: "أي دواء يجب تجنبه لدى الطفل المصاب بجدري الماء لخطر متلازمة راي؟", options: ["A) Acetaminophen", "B) Aspirin", "C) Acyclovir", "D) Calamine lotion"], correct: "B", correctTranslation: "ب: الأسبرين" },
        { text: "The pronounced lymphadenitis seen in severe diphtheria is known as:", translation: "يُعرف تضخم الغدد اللمفاوية الواضح في الخُناق الشديد باسم:", options: ["A) Bull's neck", "B) Buffalo hump", "C) Moon face", "D) Webbed neck"], correct: "A", correctTranslation: "أ: عنق الثور (Bull's neck)" },
        { text: "The causative agent of diphtheria is:", translation: "العامل المسبب للخُناق هو:", options: ["A) Corynebacterium diphtheriae", "B) Clostridium tetani", "C) Mycobacterium tuberculosis", "D) Varicella-zoster virus"], correct: "A", correctTranslation: "أ: Corynebacterium diphtheriae" },
        { text: "The causative agent of mumps is:", translation: "العامل المسبب للنكاف هو:", options: ["A) Paramyxovirus", "B) Enterovirus", "C) Salmonella typhi", "D) Corynebacterium diphtheriae"], correct: "A", correctTranslation: "أ: فيروس الباراميكسو" },
        { text: "A serious complication of mumps affecting hearing is:", translation: "من المضاعفات الخطيرة للنكاف التي تؤثر على السمع:", options: ["A) Sensorineural deafness", "B) Conductive hearing loss", "C) Otitis media", "D) Tinnitus only"], correct: "A", correctTranslation: "أ: الصمم الحسي العصبي" },
        { text: "Tetanus spores enter the body mainly through:", translation: "تدخل أبواغ الكزاز الجسم أساساً عبر:", options: ["A) Wounds such as puncture wounds or burns", "B) Respiratory droplets", "C) Fecal-oral route", "D) Insect bites"], correct: "A", correctTranslation: "أ: الجروح كالجروح الثاقبة أو الحروق" },
        { text: "Which medication is used for seizure control in tetanus?", translation: "أي دواء يُستخدم للسيطرة على النوبات في الكزاز؟", options: ["A) Diazepam", "B) Isoniazid", "C) Acyclovir", "D) Methimazole"], correct: "A", correctTranslation: "أ: الديازيبام" },
        { text: "The causative agent of tuberculosis is transmitted mainly through:", translation: "ينتقل العامل المسبب للسل أساساً عبر:", options: ["A) Droplets released by coughing and sneezing", "B) Contaminated food and water", "C) Direct skin contact", "D) Insect bites"], correct: "A", correctTranslation: "أ: الرذاذ المتطاير بالسعال والعطس" },
        { text: "The standard first-line drug given daily for 9 months in the treatment of tuberculosis is:", translation: "الدواء الأساسي الذي يُعطى بجرعة يومية لمدة 9 أشهر في علاج السل هو:", options: ["A) Isoniazid (INH)", "B) Levothyroxine", "C) Diazepam", "D) Acyclovir"], correct: "A", correctTranslation: "أ: الأيزونيازيد (INH)" },
        { text: "Typhoid fever is caused by:", translation: "تسبب حمى التيفويد:", options: ["A) Salmonella typhi", "B) Mycobacterium tuberculosis", "C) Clostridium tetani", "D) Varicella-zoster virus"], correct: "A", correctTranslation: "أ: Salmonella typhi" },
        { text: "Typhoid fever is transmitted mainly through:", translation: "تنتقل حمى التيفويد أساساً عبر:", options: ["A) Contaminated food or water", "B) Respiratory droplets", "C) Direct contact with skin lesions", "D) Insect bites"], correct: "A", correctTranslation: "أ: الطعام أو الماء الملوث" },
        { text: "According to the Egyptian obligatory immunization schedule, the BCG vaccine is given:", translation: "حسب جدول التطعيمات الإجبارية المصري، يُعطى لقاح BCG:", options: ["A) At birth", "B) At 2 months", "C) At 9 months", "D) At 12 months"], correct: "A", correctTranslation: "أ: عند الولادة" }
    ],
    truefalse: [
        { text: "Communicable diseases can spread through contact with contaminated surfaces, bodily fluids, or air.", translation: "يمكن أن تنتقل الأمراض المعدية عبر ملامسة أسطح ملوثة أو سوائل الجسم أو الهواء.", correct: "True", correctTranslation: "صح" },
        { text: "Poliomyelitis is caused by a bacterium.", translation: "يسبب شلل الأطفال بكتيريا.", correct: "False", correctTranslation: "خطأ (يسببه فيروس من الفيروسات المعوية Enteroviruses)" },
        { text: "The paralytic form of poliomyelitis can lead to permanent paralysis and respiratory arrest.", translation: "قد يؤدي الشكل الشللي لشلل الأطفال إلى شلل دائم وتوقف تنفسي.", correct: "True", correctTranslation: "صح" },
        { text: "Measles is most communicable during the prodromal (catarrhal) stage.", translation: "تكون الحصبة أكثر عدوى خلال المرحلة النزلية البادرية.", correct: "True", correctTranslation: "صح" },
        { text: "Koplik spots appear in chickenpox.", translation: "تظهر بقع كوبليك في جدري الماء.", correct: "False", correctTranslation: "خطأ (تظهر بقع كوبليك في الحصبة)" },
        { text: "Chickenpox lesions typically show macule, papule, vesicle, and crust stages, sometimes all present at once.", translation: "تمر آفات جدري الماء عادةً بمراحل البقعة والحطاطة والحويصلة والقشرة، وقد تتواجد كلها معاً أحياناً.", correct: "True", correctTranslation: "صح" },
        { text: "Aspirin is recommended for fever control in children with chickenpox.", translation: "يُنصح باستخدام الأسبرين للسيطرة على الحمى لدى الأطفال المصابين بجدري الماء.", correct: "False", correctTranslation: "خطأ (يجب تجنب الأسبرين لخطر متلازمة راي)" },
        { text: "Diphtheria is caused by Corynebacterium diphtheriae.", translation: "يسبب الخُناق جرثومة Corynebacterium diphtheriae.", correct: "True", correctTranslation: "صح" },
        { text: "In laryngeal diphtheria, airway obstruction is not a concern.", translation: "في خُناق الحنجرة، لا يُعد انسداد مجرى الهواء مصدر قلق.", correct: "False", correctTranslation: "خطأ (انسداد مجرى الهواء مصدر قلق رئيسي في هذا الشكل)" },
        { text: "Mumps is transmitted by direct contact with or droplet spread from an infected person.", translation: "ينتقل النكاف بالتلامس المباشر أو الرذاذ من شخص مصاب.", correct: "True", correctTranslation: "صح" },
        { text: "Parotid gland swelling in mumps typically reaches maximum size within 1-3 days after the gland begins to enlarge.", translation: "يصل تورم الغدة النكفية في النكاف عادةً لأقصى حجمه خلال 1-3 أيام بعد بدء التضخم.", correct: "True", correctTranslation: "صح" },
        { text: "Tetanus spores can remain viable in the environment for only a few hours.", translation: "يمكن أن تظل أبواغ الكزاز قابلة للحياة في البيئة لبضع ساعات فقط.", correct: "False", correctTranslation: "خطأ (قد تظل قابلة للحياة لسنوات عديدة)" },
        { text: "Generalized tetanus can present with jaw cramping and painful muscle stiffness throughout the body.", translation: "قد يظهر الكزاز المعمم بتشنج الفك وتيبس عضلي مؤلم في كل الجسم.", correct: "True", correctTranslation: "صح" },
        { text: "Tuberculosis is transmitted through contaminated food and water.", translation: "ينتقل السل عبر الطعام والماء الملوث.", correct: "False", correctTranslation: "خطأ (ينتقل عبر الرذاذ المتطاير بالسعال والعطس)" },
        { text: "Sputum specimens for tuberculosis should be obtained early in the morning before breakfast.", translation: "يجب أخذ عينات البلغم لتشخيص السل باكراً صباحاً قبل الإفطار.", correct: "True", correctTranslation: "صح" },
        { text: "Typhoid fever is transmitted through respiratory droplets.", translation: "تنتقل حمى التيفويد عبر رذاذ الجهاز التنفسي.", correct: "False", correctTranslation: "خطأ (تنتقل عبر الطريق البرازي الفموي بالطعام أو الماء الملوث)" },
        { text: "Oral rehydration therapy (ORT) is part of the therapeutic management of typhoid fever.", translation: "يُعد الإماهة الفموية (ORT) جزءاً من الإدارة العلاجية لحمى التيفويد.", correct: "True", correctTranslation: "صح" },
        { text: "According to the Egyptian immunization schedule, the Oral Polio Vaccine (OPV) is given at birth.", translation: "حسب جدول التطعيمات المصري، يُعطى لقاح شلل الأطفال الفموي (OPV) عند الولادة.", correct: "True", correctTranslation: "صح" }
    ],
    situations: [
        { text: "A 3-year-old unvaccinated child develops fever, sore throat, and a smooth, adherent gray membrane over the tonsils, along with pronounced neck swelling. What is the likely diagnosis, and what are the key elements of therapeutic and nursing management?", translation: "طفل عمره 3 سنوات غير مطعّم يعاني من حمى والتهاب حلق وغشاء رمادي أملس لاصق فوق اللوزتين، مع تورم واضح بالرقبة. ما التشخيص المرجح، وما العناصر الأساسية للإدارة العلاجية والتمريضية؟", answer: "This presentation is consistent with diphtheria (tonsillar-pharyngeal form), caused by Corynebacterium diphtheriae, with the pronounced lymphadenitis described as \"bull's neck.\" Therapeutic management includes equine antitoxin, antibiotics, complete bed rest, tracheostomy if airway obstruction occurs, and treatment of infected contacts and carriers; prevention relies on childhood immunization. Nursing care includes following Standard and Droplet Precautions until two cultures are negative for C. diphtheriae (with Contact Precautions for cutaneous manifestations), administering antibiotics in a timely manner, participating in sensitivity testing, keeping epinephrine available, maintaining bed rest, using suctioning as needed, observing respirations for signs of obstruction, and administering humidified oxygen as prescribed.", answerTranslation: "هذا العرض يتوافق مع الخُناق (الشكل اللوزي البلعومي) الذي تسببه جرثومة Corynebacterium diphtheriae، مع تضخم لمفاوي واضح يُوصف بـ\"عنق الثور\". تشمل الإدارة العلاجية مضاد السموم الحصاني والمضادات الحيوية والراحة التامة بالفراش وفغر الرغامى عند انسداد مجرى الهواء وعلاج المخالطين والحاملين للجرثومة؛ وتعتمد الوقاية على التطعيم. تشمل الرعاية التمريضية اتباع الاحتياطات القياسية والمحمولة بالرذاذ حتى تصبح زراعتان سلبيتين (مع احتياطات التلامس عند وجود مظاهر جلدية)، وإعطاء المضادات الحيوية في وقتها، والمشاركة في اختبار الحساسية، وتوفير الإبينفرين، والحفاظ على الراحة بالفراش، واستخدام الشفط عند الحاجة، ومراقبة التنفس لعلامات الانسداد، وإعطاء أكسجين مرطب حسب الوصفة." },
        { text: "An infant who has not received the varicella vaccine develops a highly pruritic rash that starts as macules and progresses to papules, vesicles, and crusts, with lesions in different stages present at the same time, spreading mainly to the face and trunk. What is the diagnosis, and what nursing care should be provided?", translation: "رضيع لم يتلقَّ لقاح جدري الماء أُصيب بطفح شديد الحكة يبدأ كبقع ويتطور إلى حطاطات وحويصلات وقشور، مع وجود آفات بمراحل مختلفة في وقت واحد، وينتشر أساساً على الوجه والجذع. ما التشخيص، وما الرعاية التمريضية الواجب تقديمها؟", answer: "This presentation is diagnostic of chickenpox (varicella), caused by the varicella-zoster virus. Nursing care includes maintaining Standard, Airborne, and Contact Precautions; keeping the child home away from susceptible individuals until the vesicles have dried (usually about 1 week after onset); administering skin care such as daily baths, changing clothes and linens daily, applying topical calamine lotion, keeping the child's fingernails short and clean, and applying mittens if the child scratches; keeping the child cool, since this may decrease the number of lesions; keeping the child occupied to lessen pruritus; removing loose crusts that rub and irritate the skin; teaching the child to apply pressure to pruritic areas rather than scratching; and avoiding the use of aspirin due to the risk of Reye syndrome.", answerTranslation: "هذا العرض تشخيصي لجدري الماء الذي يسببه فيروس النطاق الحماقي. تشمل الرعاية التمريضية الحفاظ على الاحتياطات القياسية والمحمولة جواً والتلامسية؛ وإبقاء الطفل بالمنزل بعيداً عن الأشخاص المعرضين حتى جفاف الحويصلات (عادة أسبوع تقريباً)؛ والعناية بالجلد كالاستحمام اليومي وتغيير الملابس والأغطية يومياً، ووضع كالامين موضعي، وتقليم الأظافر وتنظيفها، واستخدام قفازات عند الحك؛ وإبقاء الطفل بارداً لأن ذلك قد يقلل عدد الآفات؛ وإشغاله لتخفيف الحكة؛ وإزالة القشور المرتخية المهيّجة؛ وتعليمه الضغط على مناطق الحكة بدلاً من حكّها؛ وتجنب استخدام الأسبرين لخطر متلازمة راي." },
        { text: "A newborn delivered outside a healthcare facility develops, within the first weeks of life, inability to suck, excessive crying, irritability, and nuchal rigidity, followed by generalized muscle spasms. What condition is suspected, and what should nursing care focus on?", translation: "مولود وُلد خارج منشأة صحية أُصيب خلال أسابيعه الأولى بعدم قدرة على الرضاعة وبكاء مفرط وتهيج وتيبس بالرقبة، تلاه تشنجات عضلية معممة. ما الحالة المشتبه بها، وعلى ماذا يجب أن تركز الرعاية التمريضية؟", answer: "This presentation is consistent with neonatal tetanus, caused by Clostridium tetani, typically resulting from unsterile care of the umbilical cord. Therapeutic management includes tetanus immunization, antibiotics, maintaining an adequate airway and fluid and electrolyte balance, pain management, ensuring adequate caloric intake, tetanus immune globulin (TIG) therapy, local wound care, and diazepam for seizure control. Nursing care should focus on particular attention to airway and breathing, evaluating for any signs of respiratory distress, keeping appropriate emergency equipment available at all times, controlling or eliminating stimulation from sound, light, and touch during the acute phase since the infant is highly sensitive to external stimuli, preventing complications associated with prolonged immobility, attending to hydration and nutrition by monitoring IV infusion or nasogastric/gastrostomy feedings, and suctioning oropharyngeal secretions when indicated.", answerTranslation: "هذا العرض يتوافق مع كزاز المواليد الذي تسببه جرثومة Clostridium tetani، وينتج عادةً عن عناية غير معقمة بالحبل السري. تشمل الإدارة العلاجية التطعيم ضد الكزاز والمضادات الحيوية والحفاظ على مجرى هواء ملائم وتوازن السوائل والإلكتروليتات وإدارة الألم وضمان سعرات كافية، والعلاج بالغلوبولين المناعي للكزاز (TIG)، والعناية الموضعية بالجرح، والديازيبام للسيطرة على النوبات. يجب أن تركز الرعاية التمريضية على الاهتمام الخاص بمجرى الهواء والتنفس، وتقييم أي علامات ضائقة تنفسية، وتوفير معدات الطوارئ المناسبة باستمرار، والتحكم بمؤثرات الصوت والضوء واللمس أو إزالتها أثناء المرحلة الحادة نظراً لحساسية الرضيع الشديدة للمؤثرات الخارجية، ومنع مضاعفات الخمول الطويل، والاهتمام بالإماهة والتغذية بمراقبة التسريب الوريدي أو التغذية الأنفية المعدية أو عبر فغر المعدة، وشفط إفرازات البلعوم الفموي عند الحاجة." },
        { text: "A school-age child presents with a several-week history of low-grade fever, night sweats, weight loss, and a persistent cough with chest tightness, and lives in a household with a family member who has a chronic cough. What is the likely diagnosis, and what does treatment and nursing care involve?", translation: "طفل في سن المدرسة يعاني منذ عدة أسابيع من حمى خفيفة وتعرق ليلي وفقدان وزن وسعال مستمر مع ضيق بالصدر، ويعيش مع فرد من العائلة لديه سعال مزمن. ما التشخيص المرجح، وماذا يتضمن العلاج والرعاية التمريضية؟", answer: "This presentation, particularly with a household contact with a chronic cough, is suggestive of tuberculosis caused by Mycobacterium tuberculosis, which is transmitted through droplets released into the air via coughing and sneezing. The goal of therapeutic management is to achieve sterilization of the tuberculous lesion, typically using antimicrobial drugs such as a daily dose of isoniazid (INH) for 9 months, or alternatively twice-weekly dosing with directly observed therapy (DOT) for 9 months. Nursing care includes restricting the child from vigorous activities such as competitive games and contact sports, protecting the child from stress, continuing the regular immunization schedule and maintaining optimum health through proper diet, adequate rest, and avoidance of infection, obtaining sputum specimens early in the morning before breakfast, instructing the patient to use tissues when coughing and sneezing, educating about proper tissue disposal and infection control measures such as handwashing, monitoring temperature, and explaining the importance of uninterrupted drug therapy.", answerTranslation: "هذا العرض، خاصة مع وجود مخالط بالمنزل لديه سعال مزمن، يوحي بالسل الذي تسببه جرثومة Mycobacterium tuberculosis، والتي تنتقل عبر رذاذ يُطلق في الهواء بالسعال والعطس. هدف الإدارة العلاجية هو تعقيم الآفة السلية، عادةً باستخدام أدوية مضادة للميكروبات كجرعة يومية من الأيزونيازيد (INH) لمدة 9 أشهر، أو بديلاً جرعتين أسبوعياً بالعلاج المباشر المُراقَب (DOT) لمدة 9 أشهر. تشمل الرعاية التمريضية تقييد الأنشطة الشاقة كالألعاب التنافسية والرياضات التلامسية، وحماية الطفل من الضغوط، والاستمرار بجدول التطعيمات المعتاد والحفاظ على صحة مثلى بغذاء مناسب وراحة كافية وتجنب العدوى، وأخذ عينات البلغم باكراً صباحاً قبل الإفطار، وتعليم المريض استخدام المناديل عند السعال والعطس، والتثقيف حول التخلص السليم منها وإجراءات مكافحة العدوى كغسل اليدين، ومراقبة درجة الحرارة، وشرح أهمية الاستمرار دون انقطاع بالعلاج الدوائي." }
    ],
    explain: [
        { text: "Discuss the causative agent, transmission, clinical manifestations, and nursing care management of poliomyelitis.", translation: "ناقش العامل المسبب لشلل الأطفال وطرق انتقاله ومظاهره السريرية والرعاية التمريضية له.", answer: "Poliomyelitis is caused by enteroviruses, transmitted through the fecal-oral and pharyngeal-oropharyngeal routes, with an incubation period usually of 7 to 14 days. It may present in three forms: abortive or inapparent, with fever, uneasiness, sore throat, headache, anorexia, vomiting, and abdominal pain lasting a few hours to a few days; nonparalytic, with the same manifestations but more severe, including pain and stiffness in the neck, back, and legs; and paralytic, in which an initial course similar to the nonparalytic type is followed by recovery and then signs of central nervous system paralysis. Complications include permanent paralysis, respiratory arrest, hypertension, and kidney stones from bone demineralization during prolonged immobility. Nursing care management includes Contact Precautions, administering mild sedatives as needed, participating in physical therapy (moist hot packs, range-of-motion exercises), positioning the child to maintain body alignment and prevent contractures or skin breakdown, using a footboard to prevent footdrop and a pressure mattress for prolonged immobility, encouraging self-care and early ambulation with assistive devices, administering analgesics, providing a high-protein diet and bowel management, and observing for and reporting signs of respiratory paralysis such as difficulty talking, ineffective cough, and shallow rapid respirations. Prevention relies on childhood immunization.", answerTranslation: "يسبب شلل الأطفال الفيروسات المعوية، وينتقل عبر الطريقين البرازي الفموي والبلعومي الفموي، وتبلغ فترة حضانته عادةً 7-14 يوماً. وقد يظهر بثلاثة أشكال: خفي أو غير ظاهر، بحمى وعدم راحة والتهاب حلق وصداع وفقدان شهية وقيء وألم بطني يستمر ساعات إلى أيام؛ وغير شللي، بنفس الأعراض لكن أشد، مع ألم وتيبس بالرقبة والظهر والساقين؛ وشللي، حيث يتبع مساراً أولياً شبيهاً بالشكل غير الشللي تعافٍ ثم ظهور علامات شلل بالجهاز العصبي المركزي. تشمل المضاعفات شللاً دائماً وتوقفاً تنفسياً وارتفاع ضغط الدم وحصوات كلوية ناتجة عن نزع معادن العظام أثناء الخمول الطويل. تشمل الرعاية التمريضية احتياطات التلامس، وإعطاء مهدئات خفيفة عند الحاجة، والمشاركة بالعلاج الطبيعي (كمادات حارة رطبة وتمارين مدى الحركة)، ووضع الطفل بما يحافظ على استقامة الجسم ويمنع التقلصات أو تلف الجلد، واستخدام لوح قدم لمنع سقوطها وفرشة ضغط عند الخمول الطويل، وتشجيع الاعتناء بالذات والمشي المبكر بالأجهزة المساعدة، وإعطاء المسكنات، وتقديم نظام غذائي غني بالبروتين وإدارة الإخراج، ومراقبة وإبلاغ علامات الشلل التنفسي كصعوبة الكلام والسعال غير الفعال والتنفس السطحي السريع. وتعتمد الوقاية على التطعيم." },
        { text: "Discuss the clinical manifestations, therapeutic management, and nursing care of measles.", translation: "ناقش المظاهر السريرية والإدارة العلاجية والرعاية التمريضية للحصبة.", answer: "Measles is a viral disease with an incubation period of 10 to 20 days, most communicable from 4 days before to 5 days after the rash appears, mainly during the prodromal (catarrhal) stage. This stage presents with fever and malaise, followed within 24 hours by coryza, cough, conjunctivitis, and Koplik spots. The rash appears 3-4 days after onset of the prodromal stage as an erythematous maculopapular eruption on the face, spreading downward, becoming confluent in earlier sites and discrete in later sites, and assuming a brownish appearance after 3-4 days; constitutional signs include anorexia, abdominal pain, malaise, and generalized lymphadenopathy. Therapeutic management is preventive through childhood immunization, and supportive through bed rest, antipyretics, antibiotics for high-risk children to prevent secondary bacterial infection, and vitamin A supplementation. Complications include otitis media, bacterial pneumonia, obstructive laryngitis and laryngotracheitis, and encephalitis. Nursing care includes maintaining isolation until the fifth day of rash, encouraging rest during the prodromal stage, managing fever with antipyretics and avoiding chilling, using a cool-mist vaporizer and protecting the skin around the nares for coryza and cough, keeping the skin clean with tepid baths, and providing eye care such as dimming lights for photophobia and cleaning eyelids with warm saline.", answerTranslation: "الحصبة مرض فيروسي فترة حضانته 10-20 يوماً، وتكون أكثر عدوى من 4 أيام قبل ظهور الطفح إلى 5 أيام بعده، خاصة خلال المرحلة النزلية البادرية. تظهر هذه المرحلة بحمى وتوعك، تليها خلال 24 ساعة زكام وسعال والتهاب ملتحمة وبقع كوبليك. يظهر الطفح بعد 3-4 أيام من بدء المرحلة البادرية كثوران حطاطي احمراري على الوجه ينتشر نزولاً، ويصبح متلاصقاً في المواضع الأولى ومتفرقاً في المواضع اللاحقة، ويأخذ لوناً بنياً بعد 3-4 أيام؛ وتشمل الأعراض العامة فقدان الشهية وألم البطن والتوعك وتضخم الغدد اللمفاوية المعمم. تعتمد الإدارة العلاجية على الوقاية بالتطعيم، والدعم بالراحة بالفراش وخافضات الحرارة والمضادات الحيوية للأطفال عاليي الخطورة لمنع عدوى بكتيرية ثانوية، وإعطاء مكمل فيتامين أ. تشمل المضاعفات التهاب الأذن الوسطى والالتهاب الرئوي البكتيري والتهاب الحنجرة الانسدادي والتهاب الحنجرة والقصبة والتهاب الدماغ. تشمل الرعاية التمريضية العزل حتى اليوم الخامس من الطفح، وتشجيع الراحة خلال المرحلة البادرية، وإدارة الحمى بخافضاتها وتجنب البرد، واستخدام مرطب بخار بارد وحماية الجلد حول الأنف للزكام والسعال، والحفاظ على نظافة الجلد بحمامات فاترة، وتقديم عناية بالعين كتخفيف الإضاءة عند رهاب الضوء وتنظيف الجفون بمحلول ملحي دافئ." },
        { text: "Discuss the clinical manifestations, therapeutic management, and nursing care management of chickenpox (varicella).", translation: "ناقش المظاهر السريرية والإدارة العلاجية والرعاية التمريضية لجدري الماء.", answer: "Chickenpox, caused by the varicella-zoster virus, has an incubation period usually of 14-16 days and is communicable from about 1 day before eruption of lesions to about 6 days after the first crop of vesicles when crusts have formed. The prodromal stage presents with slight fever, malaise, and anorexia for the first 24 hours, followed by a highly pruritic rash that begins as a macule, progresses to a papule and then a vesicle, becomes umbilicated and cloudy, and breaks easily to form crusts, with all three stages sometimes present at once; the distribution is centripetal, spreading to the face and proximal extremities but sparse distally. Therapeutic management includes the antiviral agent acyclovir and varicella-zoster immune globulin, antihistamines for itching, skin care to prevent secondary bacterial infection, and preventive childhood immunization. Complications include secondary bacterial infections, encephalitis, varicella pneumonia, hemorrhagic varicella, and thrombocytopenia. Nursing care includes maintaining Standard, Airborne, and Contact Precautions; keeping the child home until vesicles have dried; skin care with daily baths, calamine lotion, short clean nails, and mittens if scratching; keeping the child cool and occupied; removing loose irritating crusts; teaching the child to press rather than scratch pruritic areas; and avoiding aspirin.", answerTranslation: "يسبب جدري الماء فيروس النطاق الحماقي، وفترة حضانته عادةً 14-16 يوماً، وتمتد فترة العدوى من نحو يوم قبل ظهور الآفات إلى نحو 6 أيام بعد ظهور أول دفعة من الحويصلات عند تكوّن القشور. تظهر المرحلة البادرية بحمى خفيفة وتوعك وفقدان شهية خلال أول 24 ساعة، يليها طفح شديد الحكة يبدأ كبقعة ثم يتطور لحطاطة فحويصلة، ويصبح مسرّراً وعكراً، ويتقشر بسهولة مكوّناً قشوراً، وقد توجد المراحل الثلاث معاً أحياناً؛ ويكون التوزيع مركزياً، ينتشر إلى الوجه والأطراف القريبة لكنه متناثر بالأطراف البعيدة. تشمل الإدارة العلاجية العامل المضاد للفيروسات الأسيكلوفير وغلوبولين مناعي مضاد للنطاق الحماقي، ومضادات الهيستامين للحكة، والعناية بالجلد لمنع العدوى البكتيرية الثانوية، والوقاية بالتطعيم. تشمل المضاعفات العدوى البكتيرية الثانوية والتهاب الدماغ والالتهاب الرئوي بجدري الماء وجدري الماء النزفي ونقص الصفيحات. تشمل الرعاية التمريضية الحفاظ على الاحتياطات القياسية والمحمولة جواً والتلامسية؛ وإبقاء الطفل بالمنزل حتى جفاف الحويصلات؛ والعناية بالجلد بالاستحمام اليومي والكالامين وتقليم الأظافر واستخدام القفازات عند الحك؛ وإبقاء الطفل بارداً ومشغولاً؛ وإزالة القشور المرتخية المهيّجة؛ وتعليمه الضغط بدلاً من الحك؛ وتجنب الأسبرين." },
        { text: "Discuss the clinical manifestations, complications, and nursing care management of diphtheria.", translation: "ناقش المظاهر السريرية والمضاعفات والرعاية التمريضية للخُناق.", answer: "Diphtheria, caused by Corynebacterium diphtheriae, is transmitted by direct contact with an infected person, a carrier, or contaminated articles, with an incubation period usually of 2-5 days. It presents in three forms: nasal, resembling a common cold with mucopurulent nasal discharge and possible epistaxis; tonsillar-pharyngeal, with malaise, anorexia, sore throat, low-grade fever, a smooth adherent white or gray membrane, and pronounced lymphadenitis described as \"bull's neck,\" which in severe cases can progress to toxemia, septic shock, and death within 6 to 10 days; and laryngeal, with fever, hoarseness, cough, potential airway obstruction, apprehension, dyspneic retractions, and cyanosis. Complications include toxic cardiomyopathy occurring in the second to third week and toxic neuropathy. Nursing care includes following Standard and Droplet Precautions until two cultures are negative for C. diphtheriae, with Contact Precautions for cutaneous manifestations, administering antibiotics promptly, participating in sensitivity testing, keeping epinephrine available, maintaining bed rest, using suctioning as needed, observing respirations for signs of obstruction, and administering humidified oxygen as prescribed. Therapeutic management also includes equine antitoxin, tracheostomy for airway obstruction, treatment of infected contacts and carriers, and preventive childhood immunization.", answerTranslation: "الخُناق الذي تسببه جرثومة Corynebacterium diphtheriae ينتقل بالتلامس المباشر مع شخص مصاب أو حامل للجرثومة أو أدوات ملوثة، وفترة حضانته عادةً 2-5 أيام. يظهر بثلاثة أشكال: الأنفي، يشبه الزكام مع إفرازات أنفية مخاطية قيحية واحتمال نزيف أنفي؛ واللوزي البلعومي، بتوعك وفقدان شهية والتهاب حلق وحمى خفيفة وغشاء أبيض أو رمادي لاصق وتضخم لمفاوي واضح يُوصف بـ\"عنق الثور\"، وقد يتطور بالحالات الشديدة إلى تسمم دموي وصدمة إنتانية ووفاة خلال 6-10 أيام؛ والحنجري، بحمى وبحة صوت وسعال واحتمال انسداد مجرى الهواء وقلق وتراجعات تنفسية وزُراق. تشمل المضاعفات اعتلال عضلة القلب السمي في الأسبوعين الثاني والثالث واعتلالاً عصبياً سمياً. تشمل الرعاية التمريضية اتباع الاحتياطات القياسية والمحمولة بالرذاذ حتى تصبح زراعتان سلبيتين، مع احتياطات التلامس عند وجود مظاهر جلدية، وإعطاء المضادات الحيوية فوراً، والمشاركة باختبار الحساسية، وتوفير الإبينفرين، والحفاظ على الراحة بالفراش، واستخدام الشفط عند الحاجة، ومراقبة التنفس لعلامات الانسداد، وإعطاء أكسجين مرطب حسب الوصفة. تشمل الإدارة العلاجية أيضاً مضاد السموم الحصاني وفغر الرغامى عند انسداد مجرى الهواء وعلاج المخالطين والحاملين والوقاية بالتطعيم." },
        { text: "Discuss the clinical manifestations, complications, and nursing care management of neonatal and generalized tetanus.", translation: "ناقش المظاهر السريرية والمضاعفات والرعاية التمريضية لكزاز المواليد والكزاز المعمم.", answer: "Tetanus is caused by Clostridium tetani spores found in soil, dust, and the intestinal tracts of humans and animals, which enter the body through wounds such as puncture wounds, burns, or crushed areas, with an incubation period of 3 days to 3 weeks, averaging 8 days. Local tetanus presents with persistent rigidity of muscles near the inoculation site; neonatal tetanus presents with inability to suck, excessive crying, irritability, and nuchal rigidity; and generalized tetanus presents with jaw cramping, sudden involuntary muscle spasms, painful muscle stiffness throughout the body, trouble swallowing, seizures, headache, fever and sweating, changes in blood pressure and heart rate, and high sensitivity to external stimuli such as noise, touch, or bright light. Complications include laryngospasm, fractures, pulmonary embolism, aspiration pneumonia, and breathing difficulty. Therapeutic management includes tetanus immunization, antibiotics, maintaining an adequate airway and fluid and electrolyte balance, pain management, adequate caloric intake, tetanus immune globulin (TIG) therapy, local wound care, and diazepam for seizure control. Nursing care focuses on particular attention to airway and breathing, evaluating for respiratory distress, keeping emergency equipment available, controlling stimulation from sound, light, and touch during the acute phase, preventing complications of prolonged immobility, attending to hydration and nutrition through IV infusion or nasogastric/gastrostomy feedings, and suctioning oropharyngeal secretions when indicated.", answerTranslation: "يسبب الكزاز أبواغ جرثومة Clostridium tetani الموجودة بالتربة والغبار والأمعاء لدى البشر والحيوانات، وتدخل الجسم عبر جروح كالجروح الثاقبة أو الحروق أو المناطق المسحوقة، وفترة حضانته 3 أيام إلى 3 أسابيع بمتوسط 8 أيام. يظهر الكزاز الموضعي بتيبس مستمر بعضلات موضع الإصابة؛ ويظهر كزاز المواليد بعدم القدرة على الرضاعة وبكاء مفرط وتهيج وتيبس بالرقبة؛ ويظهر الكزاز المعمم بتشنج الفك وتشنجات عضلية لا إرادية مفاجئة وتيبس عضلي مؤلم بكل الجسم وصعوبة بلع ونوبات وصداع وحمى وتعرق وتغيرات بضغط الدم ومعدل ضربات القلب وحساسية شديدة للمؤثرات الخارجية كالضوضاء واللمس والضوء الساطع. تشمل المضاعفات تشنج الحنجرة والكسور والانصمام الرئوي والالتهاب الرئوي الاستنشاقي وصعوبة التنفس. تشمل الإدارة العلاجية التطعيم والمضادات الحيوية والحفاظ على مجرى هواء ملائم وتوازن السوائل والإلكتروليتات وإدارة الألم وسعرات كافية والعلاج بالغلوبولين المناعي للكزاز والعناية الموضعية بالجرح والديازيبام للسيطرة على النوبات. تركز الرعاية التمريضية على الاهتمام الخاص بمجرى الهواء والتنفس، وتقييم الضائقة التنفسية، وتوفير معدات الطوارئ، والتحكم بمؤثرات الصوت والضوء واللمس أثناء المرحلة الحادة، ومنع مضاعفات الخمول الطويل، والاهتمام بالإماهة والتغذية عبر التسريب الوريدي أو التغذية الأنفية المعدية أو عبر فغر المعدة، وشفط إفرازات البلعوم الفموي عند الحاجة." },
        { text: "Compare natural, acquired, active, and passive immunity, and define the term vaccine.", translation: "قارن بين المناعة الطبيعية والمكتسبة والفعالة والسلبية، وعرّف مصطلح اللقاح.", answer: "Natural immunity is innate immunity or resistance to infection or toxicity that a person has without prior exposure to a specific agent. Acquired immunity, in contrast, is immunity gained from exposure to an invading agent such as bacteria, a virus, or a toxin. Within acquired immunity, active immunity is a state in which immune bodies are actively formed against specific antigens, either naturally by having had the disease clinically or subclinically, or artificially by introducing the antigen into the individual through vaccination; this type tends to be long-lasting. Passive immunity, on the other hand, is temporary immunity obtained by transfusing immunoglobulins or antitoxins, either artificially from another human or an animal that has been actively immunized against an antigen, or naturally from the mother to the fetus via the placenta; because it does not involve the individual's own immune system actively forming antibodies, it wanes over time. A vaccine is a suspension of live (usually attenuated) or inactivated microorganisms, or fractions of a microorganism, that is administered to induce active immunity and prevent infectious disease; immunization is the broader term for the process of inducing or providing either active or passive immunity artificially by administering an immunobiologic such as a vaccine or an immunoglobulin.", answerTranslation: "المناعة الطبيعية هي مناعة فطرية أو مقاومة للعدوى أو السمية يمتلكها الشخص دون تعرض سابق لعامل محدد. أما المناعة المكتسبة فهي مناعة تُكتسب من التعرض لعامل غازٍ كبكتيريا أو فيروس أو سُم. ومن ضمن المناعة المكتسبة، تُعد المناعة الفعالة حالة تتكون فيها أجسام مناعية بفعالية ضد مستضدات معينة، إما طبيعياً بالإصابة بالمرض سريرياً أو دون أعراض، أو اصطناعياً بإدخال المستضد إلى الجسم عبر التطعيم؛ وتميل هذه المناعة إلى الاستمرار طويلاً. أما المناعة السلبية فهي مناعة مؤقتة تُكتسب بنقل الغلوبولينات المناعية أو مضادات السموم، إما اصطناعياً من إنسان أو حيوان مُمَنَّع فعلياً ضد مستضد، أو طبيعياً من الأم إلى الجنين عبر المشيمة؛ ولأنها لا تعتمد على تكوين الجسم لأجسام مضادة بنفسه، فإنها تضعف مع مرور الوقت. اللقاح هو معلق من كائنات دقيقة حية (عادة مُضعَّفة) أو معطَّلة، أو أجزاء من كائن دقيق، يُعطى لإحداث مناعة فعالة والوقاية من الأمراض المعدية؛ أما التمنيع فهو المصطلح الأشمل الذي يشير إلى عملية إحداث أو توفير مناعة فعالة أو سلبية بشكل اصطناعي عن طريق إعطاء مستحضر مناعي حيوي كاللقاح أو الغلوبولين المناعي." }
    ]
};
